// Gabungkan script + token; siapkan request pertama TikTok (creator_info).
// v2: toleran — publish ke platform yang token-nya SIAP saja (bukan mensyaratkan keduanya).
const script = $('Pick Approved').first().json;
const tokens = {};
for (const t of $input.all()) {
  if (t.json.platform) tokens[t.json.platform] = t.json;
}
const tt = tokens.tiktok;
const ig = tokens.instagram;
const hasTt = !!(tt && tt.access_token);
const hasIg = !!(ig && ig.access_token);
if (!hasTt && !hasIg) throw new Error('Tabel tokens kosong - belum ada token TikTok maupun Instagram');

const hashtags = /#[\w]+/.test(script.caption || '') ? '' : '#fyp #viral #rekomendasi';
const caption = ((script.title || script.hook || '') + '\n\n' + (script.caption || '') + ' ' + hashtags + '\n\nLink di bio ??').trim().slice(0, 2000);
const videoSize = Number(script.media_bytes) || 0;
if (videoSize <= 0) throw new Error('media_bytes kosong untuk script ' + script.id);

return {
  json: {
    script_id: script.id,
    media_file: script.media_file,
    video_size: videoSize,
    caption,
    has_tt: hasTt,
    has_ig: hasIg,
    tt_access: hasTt ? tt.access_token : '',
    ig_access: hasIg ? ig.access_token : '',
    ig_user_id: hasIg ? ((ig.extra && (ig.extra.ig_user_id || ig.extra.user_id)) || null) : null
  }
};

// Bangun payload TikTok (mode inbox FILE_UPLOAD) + IG container.
const ctx = $('Prepare Publish').first().json;
const info = ($json.data && $json.data.creator_info) || {};
const opts = info.privacy_level_options || ['SELF_ONLY'];
const privacy = opts.includes('PUBLIC_TO_EVERYONE') ? 'PUBLIC_TO_EVERYONE' : opts[0];

if (ctx.video_size > 64 * 1024 * 1024) throw new Error('video > 64MB wajib chunk: ' + ctx.video_size);

const tiktokInit = {
  post_info: {
    title: ctx.caption.slice(0, 2200),
    privacy_level: privacy,
    disable_duet: false,
    disable_stitch: false,
    disable_comment: false
  },
  source_info: {
    source: 'FILE_UPLOAD',
    video_size: ctx.video_size,
    chunk_size: ctx.video_size,
    total_chunk_count: 1
  }
};

const igContainer = {
  media_type: 'REELS',
  caption: ctx.caption.slice(0, 2000),
  share_to_feed: true
};

return {
  json: {
    ...ctx,
    privacy,
    tiktokInit,
    igContainer,
    tt_access: ctx.tt_access,
    ig_access: ctx.ig_access,
    ig_user_id: ctx.ig_user_id
  }
};

// Catat submit ke posts + tandai script posted.
const ctx = $('Build Requests').first().json;
const tt = ($('TikTok Inbox Init').first().json) || {};
const igC = ($('IG Create Container').first().json) || {};
const igR = ($('IG RUpload').first().json) || {};
const out = [];

const ttOk = !!(tt.data && tt.data.publish_id);
const ttErr = ttOk ? null : JSON.stringify(tt).slice(0, 500);

const igContainerId = igC.id || igC.creation_id || null;
const igOk = !!(igR.success) && !!igContainerId;
const igErr = igOk ? null : JSON.stringify({create: igC, upload: igR}).slice(0, 500);

out.push({
  json: {
    sql: `INSERT INTO posts (script_id, platform, external_id, status, error, posted_at) VALUES (${ctx.script_id}, 'tiktok', '${ttOk ? tt.data.publish_id : ''}', '${ttOk ? 'submitted' : 'failed'}', ${ttErr ? "'" + ttErr.replace(/'/g, "''") + "'" : 'NULL'}, now());`
  }
});
out.push({
  json: {
    sql: `INSERT INTO posts (script_id, platform, external_id, status, error, posted_at) VALUES (${ctx.script_id}, 'instagram', '${igOk ? igContainerId : ''}', '${igOk ? 'submitted' : 'failed'}', ${igErr ? "'" + igErr.replace(/'/g, "''") + "'" : 'NULL'}, now());`
  }
});
return out;

// Refresh token TikTok (POST form) & Instagram (GET ig_refresh_token).
const out = [];
for (const item of $input.all()) {
  const t = item.json;
  if (t.platform === 'tiktok') {
    const body = new URLSearchParams({
      client_key: $env.TIKTOK_CLIENT_KEY || '',
      client_secret: $env.TIKTOK_CLIENT_SECRET || '',
      grant_type: 'refresh_token',
      refresh_token: t.refresh_token || ''
    }).toString();
    out.push({
      json: {
        platform: 'tiktok',
        method: 'POST',
        url: 'https://open.tiktokapis.com/v2/oauth/token/',
        contentType: 'application/x-www-form-urlencoded',
        body,
        headers: []
      }
    });
  } else if (t.platform === 'instagram') {
    out.push({
      json: {
        platform: 'instagram',
        method: 'GET',
        url: 'https://graph.facebook.com/v21.0/oauth/access_token?grant_type=ig_refresh_token&fb_exchange_token=' + encodeURIComponent(t.access_token),
        contentType: '',
        body: '',
        headers: []
      }
    });
  }
}
return out;

// Simpan hasil refresh (toleran: kalau gagal, token lama tetap dipakai).
const req = $('Build Refresh Requests').first().json;
const res = $json;
const nowSec = Math.floor(Date.now() / 1000);
const out = [];
if (req.platform === 'tiktok' && res.access_token) {
  const exp = new Date((nowSec + (res.expires_in || 86400)) * 1000).toISOString();
  out.push({ json: { platform: 'tiktok', access: res.access_token, refresh: res.refresh_token || '', exp } });
} else if (req.platform === 'instagram' && res.access_token) {
  const exp = new Date((nowSec + (res.expires_in || 60 * 86400)) * 1000).toISOString();
  out.push({ json: { platform: 'instagram', access: res.access_token, refresh: '', exp } });
}
return out;

